#ifdef GL_ES
precision mediump float;
#endif

/*****************************************************
 * 1) ROTATION HELPERS (vec3, float)
 *****************************************************/
vec3 rotateXVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        p.x,
        c*p.y - s*p.z,
        s*p.y + c*p.z
    );
}

vec3 rotateYVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
         c*p.x + s*p.z,
         p.y,
        -s*p.x + c*p.z
    );
}

vec3 rotateZVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        c*p.x - s*p.y,
        s*p.x + c*p.y,
        p.z
    );
}

/*****************************************************
 * 2) GLOBAL CONSTANTS & SETTINGS
 *****************************************************/
#define PI      3.14159265359
#define TWO_PI  6.28318530718

// We only keep the Trefoil knot with 2 wires
#define WIRES_PER_KNOT   2

#define N_SAMPLES        70
#define WIRE_RADIUS      0.08

// Scene scale
#define SCENE_SCALE      1.2

// Spiral spin speed for the wire twisting
#define ROT_SPEED        10.0

// Trefoil's twist factor
float twistTrefoil = 18.0;

/*****************************************************
 * 3) TREFOIL (closed)
 *****************************************************/
vec3 trefoilBasePos(float t)
{
    float s = 0.15;
    return s * vec3(
        sin(t) + 2.0*sin(2.0*t),
        cos(t) - 2.0*cos(2.0*t),
        -sin(3.0*t)
    );
}

vec3 trefoilTangent(float t)
{
    float s = 0.15;
    float dx = cos(t) + 4.0*cos(2.0*t);
    float dy = -sin(t) + 4.0*sin(2.0*t);
    float dz = -3.0*cos(3.0*t);
    return normalize(s * vec3(dx, dy, dz));
}

/*****************************************************
 * 4) FRAME FOR TREFOIL
 *****************************************************/
struct FrameData {
    vec3 pos;
    vec3 tangent;
    vec3 normal;
    vec3 binormal;
};

FrameData getTrefoilFrame(float t)
{
    FrameData f;
    vec3 p = trefoilBasePos(t);
    vec3 d = trefoilTangent(t);

    // scale
    p *= SCENE_SCALE;

    // build normal/binormal
    vec3 up = vec3(0,1,0);
    vec3 n  = normalize(cross(d, up));
    if(length(n) < 0.00001) {
        up = vec3(1,0,0);
        n  = normalize(cross(d, up));
    }
    vec3 b = cross(d, n);

    f.pos      = p;
    f.tangent  = d;
    f.normal   = n;
    f.binormal = b;
    return f;
}

/*****************************************************
 * 5) DOUBLE-WIRE SPIRAL OFFSET FOR TREFOIL
 *****************************************************/
vec3 getTrefoilWireCenterPos(int wireId, float t, float time)
{
    FrameData fd = getTrefoilFrame(t);

    // The Trefoil is closed, so max param is 2π
    float u     = t / TWO_PI;
    float twist = twistTrefoil;

    // wire #1 => phase=0, wire #2 => phase=π
    float phaseShift = (wireId == 0)? 0.0 : PI;

    float twistAngle = ROT_SPEED*time
                     + twist*(u*TWO_PI)
                     + phaseShift;

    // radius for the wire offset
    float radius = 0.03 * SCENE_SCALE;
    vec3 offset = radius * (
        cos(twistAngle)*fd.normal +
        sin(twistAngle)*fd.binormal
    );
    return fd.pos + offset;
}

/*****************************************************
 * 6) CAMERA
 *****************************************************/
struct Camera {
    vec3 ro;
    vec3 forward;
    vec3 right;
    vec3 up;
};

Camera getCamera(float time, vec2 mouse, vec2 resolution)
{
    // start at (0,0,4)
    vec3 baseCam = vec3(0.0, 0.0, 4.0);
    vec3 ro = baseCam;

    bool userClicking = (iMouse.z > 0.5);

    if(!userClicking)
    {
        // AUTO SPIN around Y
        float spin = 0.001 * time;
        ro = rotateYVec(ro, spin);
    }
    else
    {
        // MANUAL ROTATION with mouse
        float yaw   = (mouse.x / resolution.x)*2.0*PI - PI;
        float pitch = (mouse.y / resolution.y)*1.0*PI - 0.5*PI;
        ro = rotateYVec(ro, yaw);
        ro = rotateXVec(ro, pitch);
    }

    // build camera basis
    vec3 fw = normalize(-ro);
    vec3 rt = normalize(cross(fw, vec3(0,1,0)));
    vec3 up = cross(rt, fw);

    Camera c;
    c.ro      = ro;
    c.forward = fw;
    c.right   = rt;
    c.up      = up;
    return c;
}

vec3 projectToScreen(vec3 p3D, Camera cam)
{
    float focal = 3.5;

    vec3 diff = p3D - cam.ro;
    float cx  = dot(diff, cam.right);
    float cy  = dot(diff, cam.up);
    float cz  = dot(diff, cam.forward);

    // near or behind camera => clip
    if(cz < 0.001) {
        return vec3(9999.0, 9999.0, 9999.0);
    }

    float ndcX = focal * cx / cz;
    float ndcY = focal * cy / cz;
    return vec3(ndcX, ndcY, cz);
}

/*****************************************************
 * 7) DISTANCE FROM PIXEL TO LINE SEGMENT (2D)
 *****************************************************/
float distToSegment2D(vec2 P, vec2 A, vec2 B)
{
    vec2 v  = B - A;
    vec2 w  = P - A;
    float c1 = dot(w,v);
    if(c1 <= 0.0) {
        return length(P - A);
    }
    float c2 = dot(v,v);
    if(c2 <= c1) {
        return length(P - B);
    }
    float b = c1 / c2;
    vec2 Pb = A + b*v;
    return length(P - Pb);
}

/*****************************************************
 * 8) SIMPLE HASH & NOISE
 *    (Minimal code for swirling smoke)
 *****************************************************/
float hash12(vec2 p)
{
    // classic GLSL “pseudo-random” hash
    const float K = 2.49999999;
    return fract(sin(dot(p, vec2(37.1, 61.7))) * 43758.5453 + K);
}

// 2D fractional Brownian motion
float noise2D(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash12(i + vec2(0,0));
    float b = hash12(i + vec2(1,0));
    float c = hash12(i + vec2(0,1));
    float d = hash12(i + vec2(1,1));

    vec2 u = f*f*(3.0 - 2.0*f);
    return mix( mix(a, b, u.x),
                mix(c, d, u.x), u.y );
}

float fbm(vec2 p)
{
    float f = 0.1;
    float s = 0.80;
    for(int i=0; i<5; i++)
    {
        f += noise2D(p)*s;
        p *= 2.02;
        s *= 0.5;
    }
    return f;
}

/*****************************************************
 * 9) MIN DISTANCE TO TREFOIL (in 2D screen space)
 *****************************************************/
float getMinDistToTrefoil(vec2 uv, float time, Camera cam)
{
    float tMax = TWO_PI;
    float minD = 9999.0;

    for(int wireId=0; wireId<WIRES_PER_KNOT; wireId++)
    {
        for(int i=0; i<N_SAMPLES; i++)
        {
            float t0 = float(i)*(tMax/float(N_SAMPLES));
            float t1 = float(i+1)*(tMax/float(N_SAMPLES));
            if(i == (N_SAMPLES-1)) {
                t1 = 0.0; // wrap
            }

            vec3 p0_3D = getTrefoilWireCenterPos(wireId, t0, time);
            vec3 p1_3D = getTrefoilWireCenterPos(wireId, t1, time);

            vec3 p0_clip = projectToScreen(p0_3D, cam);
            vec3 p1_clip = projectToScreen(p1_3D, cam);
            if(p0_clip.z>9000.0 && p1_clip.z>9000.0) {
                continue;
            }

            float dLine = distToSegment2D(uv, p0_clip.xy, p1_clip.xy);
            minD = min(minD, dLine);
        }
    }
    return minD;
}

/*****************************************************
 * 10) SMOKE FIELD
 *****************************************************/
vec3 getSmokeColor(vec2 uv, float time, float minDistToKnot)
{
    // SHIFT upward => smoke "rises"
    vec2 p = uv;
    float speedUp = 0.6;  // upward scrolling speed
    p.y += time * speedUp;

    // Gentle horizontal sway
    float swayFreq = 0.50;
    float swayAmp  = 0.01;
    p.x += swayAmp * sin( p.y * swayFreq + time );

    // Additional swirl near knot
    float swirlStrength = 0.3;
    float d = minDistToKnot;
    float swirlFactor = clamp(1.0 - d/0.4, 0.0, 1.0);
    float angle = swirlStrength * swirlFactor;
    float ca = cos(angle), sa = sin(angle);
    vec2 dp = p - uv;
    vec2 rp = vec2(
        dp.x*ca - dp.y*sa,
        dp.x*sa + dp.y*ca
    );
    p = uv + rp;

    // Fractal noise
    float n = fbm( p * 2.0 );

    // Blue smoke
    vec3 smokeDark  = vec3(0.000,0.000,0.000);
    vec3 smokeLight = vec3(0.000,0.251,1.000);
    vec3 baseSmoke  = mix(smokeDark, smokeLight, n);

    // Fade out near top
    float fadeTop = clamp(10.5 - uv.y*1.5, 0.0, 1.0);
    return baseSmoke * fadeTop;
}

/*****************************************************
 * 11) MAIN
 *****************************************************/
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized coords
    vec2 uv = (2.0*fragCoord - iResolution.xy)/iResolution.y;

    // camera
    Camera cam = getCamera(iTime, iMouse.xy, iResolution.xy);

    //---------------------------------------------
    // 1) Distance to knot
    //---------------------------------------------
    float minD = getMinDistToTrefoil(uv, iTime, cam);

    //---------------------------------------------
    // 2) Smoke & background
    //---------------------------------------------
    vec3 smokeCol = getSmokeColor(uv, iTime, minD);

    float grad = 0.5 * (uv.y + 1.0);
    grad = clamp(grad, 0.0, 1.0);
    vec3 colTop    = vec3(0.5); 
    vec3 colBottom = vec3(0.5);
    vec3 bgGrad    = mix(colBottom, colTop, grad);

    float smokeAlpha = 0.8; 
    vec3 bgColor = mix(bgGrad, smokeCol, smokeAlpha);

    //---------------------------------------------
    // 3) VIBRATIONAL RINGS AROUND THE KNOT
    //---------------------------------------------
    // Feel free to tweak these:
    float frequency = 30.0; // more => tighter rings
    float speed     = 15.0;  // ring animation speed
    float wave      = sin(minD * frequency - iTime * speed);

    // wave is in [-1..1]; shift to [0..1]
    float vibr = 2.5 + 2.5 * wave;

    // sharpen lines with smoothstep => narrower band
    vibr = smoothstep(0.45, 0.55, vibr);

    // color & how strongly the rings appear
    vec3 ringColor  = vec3(0.000,0.122,0.400); // bright blue
    float intensity = 0.4;

    // blend ring color with our background
    vec3 vibColor   = mix(bgColor, ringColor, vibr * intensity);

    //---------------------------------------------
    // 4) Now overlay the trefoil wires in front
    //---------------------------------------------
    float closestZ = 99999.0;
    vec3 finalColor = vibColor;

    float tMax = TWO_PI;
    for(int wireId=0; wireId<WIRES_PER_KNOT; wireId++)
    {
        for(int i=0; i<N_SAMPLES; i++)
        {
            float t0 = float(i)*(tMax/float(N_SAMPLES));
            float t1 = float(i+1)*(tMax/float(N_SAMPLES));
            if(i == (N_SAMPLES-1)) {
                t1 = 0.0; // wrap
            }

            vec3 p0_3D = getTrefoilWireCenterPos(wireId, t0, iTime);
            vec3 p1_3D = getTrefoilWireCenterPos(wireId, t1, iTime);

            vec3 p0_clip = projectToScreen(p0_3D, cam);
            vec3 p1_clip = projectToScreen(p1_3D, cam);
            if(p0_clip.z>9000.0 && p1_clip.z>9000.0) {
                continue;
            }

            float dist2Line = distToSegment2D(uv, p0_clip.xy, p1_clip.xy);
            if(dist2Line < WIRE_RADIUS)
            {
                float segZ = min(p0_clip.z, p1_clip.z);
                if(segZ < closestZ)
                {
                    closestZ = segZ;

                    // wire #1 => black, wire #2 => white
                    vec3 baseColor = (wireId == 0)
                                     ? vec3(0.0,0.0,0.0)
                                     : vec3(1.0,1.0,1.0);

                    float f = 1.0 - clamp(dist2Line / WIRE_RADIUS, 0.0, 1.0);
                    float shade = 0.9 + 0.1*f;

                    vec3 wireColor = baseColor * shade;
                    wireColor /= (0.9 + 0.03 * segZ);

                    finalColor = wireColor;
                }
            }
        }
    }

    fragColor = vec4(finalColor, 1.0);
}
